    aliases: ["宝石珊瑚", "红珊瑚"],
    taxonomy: { phylum: "刺胞动物门", class: "珊瑚纲", order: "软珊瑚目", family: "红珊瑚科", genus: "红珊瑚属" },
    summary: "骨骼呈深红色的地中海珊瑚，生长极其缓慢，因被大量采捞制作珠宝而资源严重衰退，是中国国家一级保护动物。",
    description: "红珊瑚群体呈树状，高约 10–25 cm，中轴骨由致密的红色碳酸钙和角质构成，坚硬如石；水螅体白色半透明，展开时像一朵朵小花。主干直径每年仅增长约 0.2–0.5 mm，生长极其缓慢。\n\n它生活在地中海和东大西洋的岩壁、洞穴与弱光海区，靠水螅体滤食浮游生物和有机碎屑。红珊瑚既能进行有性繁殖，也能靠断裂的枝条再生，性成熟需要多年。密集的红珊瑚丛为鱼、虾、蟹等提供栖息场所。由于骨骼色泽艳丽，它长期被采捞制作珠宝首饰，过度捕捞和非法贸易使资源严重衰退；1999 年地中海热浪还曾造成西北地中海红珊瑚大面积死亡。红珊瑚被列为 IUCN 濒危等级，也是中国国家一级保护野生动物。",
    habitat: "地中海与东大西洋的岩壁、洞穴和弱光海区，多在水深数十米处",
