    category: "other-invertebrates",
    aliases: ["月亮水母", "海月"],
    taxonomy: { phylum: "刺胞动物门", class: "钵水母纲", order: "旗口水母目", family: "海月水母科", genus: "海月水母属" },
    summary: "半透明的圆盘状水母，伞面有四个醒目的马蹄形生殖腺，常见于近岸海域，触手短而毒性微弱，是水族馆常见的展示对象。",
    description: "海月水母伞径通常 10–25 cm，最大可达 40 cm，伞体半透明，边缘有数百条细短触手，伞面中央能透出四个马蹄形或环形的生殖腺，胃腔的辐管呈四射状，因此得名海月。\n\n它的生活史有世代交替：水母体释放精卵，受精卵发育成浮浪幼虫，附着后变为水螅体，水螅体通过横裂生殖产生碟状幼体，再长成水母体。海月水母捕食浮游动物、鱼卵和幼鱼，用触手粘住猎物后送入口中。在富营养化海域，它常大量暴发，与鱼类争夺食物，也会堵塞渔网和发电厂的进水口。它广泛分布于全球温带和热带近岸海域，中国黄海、渤海和东海都能见到；刺细胞毒性弱，敏感者接触后可能出现皮肤发红。",
