    aliases: ["葡萄牙战舰", "蓝瓶水母"],
    taxonomy: { phylum: "刺胞动物门", class: "水螅纲", order: "管水母目", family: "僧帽水母科", genus: "僧帽水母属" },
    summary: "由多个特化个体组成的群体性管水母，形似蓝色小帆船，被称作葡萄牙战舰，触手可长达数十米，蜇伤剧痛危险。",
    description: "僧帽水母的浮囊体呈蓝紫色、半透明，形似僧帽或船帆，长 9–30 cm，内部含气体可调节浮力，靠风推动漂移；浮囊下方垂着多组触手，最长可伸达 10–30 m，触手上密布刺细胞。它属于水螅纲管水母目，与常见的水母不是同一类群。\n\n它不是单一动物，而是由水螅体、生殖体、营养体、指状体等多种特化个体组成的群体。触手麻痹小鱼和幼鱼后，由营养体消化，营养在群体内共享。僧帽水母漂浮在热带和亚热带海面，常被风和洋流送到海滩，搁浅后仍能刺伤皮肤。蜇伤会引起剧烈疼痛、红肿和过敏反应，严重时危及生命。它广泛分布于全球热带、亚热带海域，中国南海和东海也能见到，是海滩上需要警惕的危险生物。",
    habitat: "热带与亚热带开阔海面，靠风力与洋流漂流",
