    summary: "触手末端膨大如奶嘴的海葵，与多种小丑鱼形成互利共生，是热带珊瑚礁和海水观赏水族中的常见物种。",
    description: "奶嘴海葵是单体海葵，口盘直径约 5–15 cm，触手众多，末端膨大成球状或泡状，形似奶嘴。体色随光照和体内共生藻而变化，可从红色、绿色到褐色，基部附着在礁石上，触手可多达数百条，随水流轻轻摆动。\n\n它体内有虫黄藻，靠藻类光合作用获得大部分营养，同时也捕食浮游动物。奶嘴海葵与小丑鱼互利共生：小丑鱼获得庇护，海葵则得到清洁和招引猎物。它可通过纵裂进行无性繁殖，也能有性繁殖。奶嘴海葵分布于印度洋—西太平洋珊瑚礁，从红海到日本南部和澳大利亚都能见到，为多种珊瑚礁鱼类提供栖息地，也是海水观赏水族最常见的海葵之一，饲养需要较强光照和稳定水质。",
    habitat: "热带珊瑚礁与岩礁区，常附着在礁石缝隙和浅水区",
