    summary: "具五条腕的大型海星，五腕展开可达 40 cm，以贝类为食，原产北太平洋，被船只带入澳大利亚后成为破坏性入侵物种。",
    description: "多棘海盘车通常有 5 条腕，偶见 4 或 6 条，五腕展开直径可达 30–40 cm，体色从黄橙、橙红到紫色，表面密布小棘和叉棘，体盘大而厚实。\n\n它是捕食性海星，主要吃贻贝、牡蛎、扇贝等双壳贝类，也取食螺和小型甲壳动物。捕食时把胃翻出体外，直接消化贝壳里的肉。一只雌海星可产卵数千万粒，幼体浮游数周后沉降；腕和体盘损伤后还能再生，再生能力在动物界十分突出。多棘海盘车原产日本、朝鲜半岛、中国北部沿海和俄罗斯远东，20 世纪随船舶压舱水传入澳大利亚塔斯马尼亚，在当地缺乏天敌，大量吞食养殖贝类，成为澳大利亚最严重的海洋入侵物种之一。",
    habitat: "潮间带至浅海的沙泥底、岩礁和贝类养殖区",
