    category: "other-invertebrates",
    aliases: ["海胆", "紫胆"],
    taxonomy: { phylum: "棘皮动物门", class: "海胆纲", order: "拱齿目", family: "长海胆科", genus: "长海胆属" },
    summary: "体表密布紫黑色棘刺的常见海胆，用亚里士多德提灯刮食礁石上的海藻，在中国东南沿海是重要的渔业资源。",
    description: "紫海胆壳径约 4–8 cm，棘刺粗壮、紫黑色或暗紫色，长 2–3 cm；壳面分为五条步带和间步带，管足从棘间伸出，用于运动和附着。口部有由五枚齿组成的亚里士多德提灯，用来刮取海藻。\n\n它夜行性，白天藏在岩缝和洞穴中，夜间出洞刮食褐藻、绿藻和红藻。夏季繁殖，雌雄个体把精卵排入海水，受精后发育成浮游幼体，约 1 个月后变态沉底。紫海胆通过啃食海藻控制藻类数量，维持海藻林与海胆之间的平衡；数量过多时会啃光海藻，形成光秃秃的海胆荒。它分布于中国东南沿海、日本南部和朝鲜半岛沿岸，是名贵的食用海胆，生殖腺即海胆黄，经济价值高，目前以捕捞和养殖供应市场。",
    habitat: "潮间带至浅海岩礁区，白天藏身于礁缝石洞",
