    description: "医蛭体长 8–15 cm，伸展时可达 20 cm，体背绿褐色，带橙黄色纵纹和黑斑，腹面暗绿色。身体扁平，前后各有一个吸盘，前吸盘中央是口，口内有 3 枚颚，每枚颚上排列着细齿，咬出的伤口呈 Y 字形。\n\n它生活在淡水池塘、沼泽和缓流中，靠吸食哺乳动物等温血动物的血液为生，一次吸血后可数月不进食。医蛭寻找宿主依靠感知温度、化学物质和水体振动。它的唾液含抗凝血的水蛭素、麻醉物质和血管扩张物质，使伤口持续流血却不感到疼痛。医蛭雌雄同体，异体受精，在潮湿土壤中产卵茧。水蛭素已启发了多种抗凝药物，活体医蛭至今仍用于断指再植和皮瓣移植术后的淤血处理。它分布于欧洲，因过度采集和湿地减少，野生种群已明显下降。",
