    description: "沐浴角骨海绵的群体呈团块状或半球形，直径 10–30 cm，体表有较大的出水孔。体内由角骨海绵丝构成弹性网状骨架，夹杂少量硅质骨针；活体呈黑褐、灰褐或深褐色，干燥漂白后变成米黄色。\n\n它固着在岩礁海底生活，没有神经系统和器官，靠领细胞鞭毛带动水流，滤食海水中的细菌和有机微粒，有净化海水的作用，也为小型生物提供栖息空间。海绵可行有性繁殖，也能通过出芽和断裂进行无性繁殖，幼体浮游一段时间后附着定居。沐浴角骨海绵分布于地中海及邻近大西洋海域，如爱琴海和北非沿岸，其弹性骨架干燥后就是天然浴海绵，采集业曾十分兴盛；1980 年代地中海暴发的海绵病害重创了这一产业，如今天然海绵采集已大幅减少。",
