    description: "日本沙蚕体长 10–20 cm，身体细长分节，每节两侧有一对疣足，疣足上生有刚毛，帮助它在泥沙中穿行。头部有触手和触须，吻可以翻出，吻端带颚齿；体色红褐、绿褐或黄褐色，随环境变化。\n\n它穴居或穿梭于泥沙、贝壳碎屑中，常见于河口和滩涂，耐低氧和污染。食性为杂食与腐食，取食沉积物中的有机碎屑、藻类和小型动物。繁殖期，虫体后部发生变化，成熟个体成群游向水面释放精子和卵子，这一现象称为群浮；受精卵发育成担轮幼虫，浮游一段时间后沉底变态。日本沙蚕分布在中国沿海、日本和朝鲜半岛的河口滩涂，能分解有机质，是鱼类、蟹类和涉禽的食物，也常被采集作钓饵和养殖饵料。",
    habitat: "潮间带和河口的泥沙、泥滩，常见于富有机质的底质",
