    description: "鹿角杯形珊瑚的群体呈灌木状或鹿角状，分枝细密，表面布满小水螅体，活体多呈粉红、淡黄或褐色。它属于石珊瑚，能分泌碳酸钙骨骼，与虫黄藻共生，靠藻类光合作用提供大部分能量，因此需要充足的光照。\n\n它生活在热带珊瑚礁的浅水区，从礁坪到礁坡都能见到，喜欢光照充足、水流适中的环境。环境压力大时，鹿角杯形珊瑚会把体内的虫黄藻排出，出现白化现象，如果持续时间过长就会死亡。它分布于印度洋和太平洋的珊瑚礁，是研究珊瑚白化和恢复力的常用物种。海水升温、污染和过度捕捞都会威胁珊瑚礁健康，保护珊瑚礁需要减少碳排放并控制局部污染，珊瑚礁保护区的建立也有助于它的恢复。",
