    summary: "呈扇形网格状的大型软珊瑚，靠虫黄藻和滤食获取营养，分布在加勒比海，是海扇类群的代表物种之一。",
    description: "柳珊瑚的群体呈扁平的扇形，由许多细枝交织成网状，表面覆盖着一层紫色、黄色或褐色的组织，水螅体细小而密集，展开时像一层薄薄的绒毛。它属于软珊瑚，内部有柔韧的骨针支撑，可以随水流摆动。\n\n它生活在加勒比海的珊瑚礁和岩礁区，常附着在礁石和海流经过的地方，靠虫黄藻光合作用和滤食浮游生物获取营养。柳珊瑚的扇形结构能迎向水流，提高滤食效率，也为小鱼和无脊椎动物提供躲藏处。它分布于西大西洋热带海域，是海扇类群中分布较广的种类。海水升温、疾病和污染会影响它的生长，加勒比海的海扇在近几十年曾因疾病大量减少。保护珊瑚礁对它的种群延续十分关键。",
