    description: "地毯海葵的口盘可伸展到 1 m 以上，密布短而细的触手，触手呈黄绿、褐绿或紫褐色，铺展在沙地和礁石上，看起来像一块厚厚的地毯。它属于大型海葵，身体基部附着在礁石或沙中。\n\n它生活在印度—太平洋珊瑚礁的浅水沙地和礁坪，靠触手捕捉小鱼、虾类等猎物，也吸收虫黄藻提供的营养。地毯海葵与小丑鱼、海葵虾等形成共生关系，这些动物靠体表黏液避免被蜇伤，同时为海葵清理和吸引猎物。蜇刺对人类的刺激较强，接触后可能红肿疼痛。它分布于印度洋和西太平洋，包括中国南海，是珊瑚礁生态中显眼的组成部分。潜水时看到它，最好保持一定距离，不要用手触碰。",
