    summary: "世界上最大的水母之一，伞径可达 2 m，触手长达数十米，生活在寒冷海域，蜇伤可致疼痛和过敏。",
    description: "狮鬃水母的伞体呈扁平圆盘状，直径通常 30–60 cm，最大记录可达 2 m 以上，颜色多为红褐、黄褐或淡红色。伞缘垂下大量细长的触手，像狮子的鬃毛一样密集，触手最长可达 30 m 以上。\n\n它生活在北极、北大西洋和北太平洋的寒冷海域，是冷水性大型水母的代表。狮鬃水母捕食浮游动物、小鱼和其他水母，靠触手上的刺细胞麻痹猎物。它的生活史包含水螅体和水母体两个阶段，水螅体附着在海底，通过横裂产生小水母。狮鬃水母的蜇伤会引起疼痛、红肿和过敏反应，敏感人群需要及时就医；它在海洋生态中是大型捕食者，也是海龟和翻车鱼的食物，它们的数量受海水温度影响。",
