    description: "澳大利亚箱形水母的伞体呈立方形，半透明，直径约 15–25 cm，伞体四角各伸出成束的触手，每条触手可长达 3 m，上面密布刺细胞。它有 24 只眼睛，其中一些具备成像能力，能主动游动和避开障碍。\n\n它生活在澳大利亚北部和东南亚部分海域的浅水海岸，常在涨潮时靠近沙滩，游泳速度快，能主动捕食小鱼和虾类。箱形水母的毒液毒性极强，蜇伤后可在数分钟内引起剧痛、呼吸困难甚至心跳骤停，是世界上最危险的海洋动物之一。澳大利亚海滩在箱形水母季节会设置防护网并张贴警示，被蜇后应立即呼救并进行急救处理。在箱形水母季节，应避免在无人看管的海滩下水。",
