    description: "马粪海胆的壳呈半球形，壳径约 3–5 cm，表面密布短而粗的棘刺，颜色多为暗绿、黑绿或紫褐色，棘刺长度与壳径相近，整体看上去像一个深色的小刺球。它的口部有亚里士多德提灯，用来刮食海藻。\n\n它生活在潮间带至浅海的岩礁区，白天藏在礁缝和石洞中，夜间出洞取食褐藻、绿藻和红藻。马粪海胆在中国北方沿海和日本很常见，是重要的食用海胆，生殖腺即海胆黄，味道鲜美，价格较高。捕捞和养殖是该地区的重要渔业之一；海胆数量过多时会啃光海藻，形成海胆荒，影响珊瑚礁和藻场的生态平衡，因此需要科学管理采捕强度。它的壳和棘刺也常被冲上海滩，成为海滩上的自然物。",
