    description: "海百合的外形像一株小植物，身体中央是杯状体，伸出约 10 条细长的腕，腕两侧排列着羽状的小枝，颜色多为红色、橙色、黄色或褐色，展开时像一朵花。它属于海百合纲，是棘皮动物中形态最古老的一类。\n\n它生活在东北大西洋的岩礁和砾石底，水深从浅海到较深处，成体没有柄，靠腕基部的卷枝攀附在岩石、海藻或其他生物上，用羽状腕捕捉浮游生物和有机颗粒。海百合的幼体有柄，附着后经过变态，成体才脱离柄自由生活。它分布于东北大西洋和地中海，常成群出现。海百合对水质和底质变化较敏感，可作为海洋环境监测的指示生物之一。海百合在古生代海洋中曾非常繁盛。",
