    description: "双齿围沙蚕体长可达 20–30 cm，身体细长分节，每节两侧有一对发达的疣足，疣足上带刚毛，头部有触手和触须，吻端有两枚大颚，因此称双齿围沙蚕。体色青绿、红褐或黄褐色，随环境变化。\n\n它生活在中国沿海的潮间带泥滩和河口，钻洞而居，耐低氧和污染，取食泥沙中的有机碎屑、藻类和小型动物。双齿围沙蚕是重要的经济多毛类，被大量采集作为钓鱼活饵和对虾养殖的饵料，部分产区还开展人工养殖。它在滩涂生态中能促进有机质分解、改善底质，也可作为环境监测的指示生物；过度采挖会破坏滩涂底质，采捕时应控制强度。在滩涂生态修复中，它也能帮助改善底质。",
