    description: "玻璃海鞘的成体呈长筒状，长约 5–12 cm，身体半透明，可以隐约看到内部的消化道和鳃囊，体表柔软，有入水管孔和出水管孔两个开口。它属于脊索动物门尾索动物亚门，幼体有脊索和尾，成体固着后脊索消失。\n\n它生活在浅海岩礁、码头、船体和养殖设施上，常成群附着，靠鳃囊滤食浮游生物和有机颗粒。玻璃海鞘是研究脊索动物演化和发育生物学的经典模式生物，其基因组已被完整测序。它是一种常见的海洋污损生物，大量附着会增加船体阻力、堵塞管道，影响水产养殖；防治主要靠定期清理、防污涂料和设施维护，同时要注意避免随船体传播到新的海区。海鞘的幼体浮游期是扩散的关键阶段。",
