    description: "华枝睾吸虫成虫体长约 1–2.5 cm，身体扁平，呈柳叶形，前端有口吸盘，腹面有腹吸盘，体内有分枝状的睾丸，因此得名；它寄生在人或哺乳动物的胆管内，靠吸盘附着并吸食胆汁和血液。\n\n它的生活史需要两个中间宿主：虫卵随粪便排出，被淡水螺吞食后发育为尾蚴，尾蚴钻入淡水鱼、虾体内形成囊蚴；人若生食或半生食含囊蚴的淡水鱼虾，就可能感染，囊蚴在人体内发育为成虫，引起肝吸虫病，出现腹痛、腹泻、胆管炎等症状，长期感染还与胆管癌有关。华枝睾吸虫主要流行于中国南方、朝鲜半岛和越南北部。预防的关键是把淡水鱼虾彻底煮熟，不食用生鱼片和腌制生鱼，处理生熟食材的砧板刀具要分开，粪便无害化处理和消灭中间宿主也有助于控制传播。",
