    description: "水螅的身体呈细长的管状，长约 0.5–1.5 cm，基部有基盘附着在水草或石块上，另一端是口，口周围有一圈细长的触手，触手上密布刺细胞。体色多为淡绿、淡褐或灰白色，身体可以伸缩和弯曲。\n\n它生活在池塘、湖泊和缓流的淡水水体中，附着在水草、石块和水生植物上，用触手捕捉水蚤、小型甲壳动物和昆虫幼虫，刺细胞释放毒素麻痹猎物后送入口中。水螅的再生能力极强，身体被切碎后每段都能重新长成完整个体，因此是研究再生和身体极性形成的经典实验动物。它通常通过出芽进行无性繁殖，在环境不良时也会进行有性繁殖。水螅对水质变化较敏感，可作为淡水水质监测的指示生物。",
