    description: "纽虫的身体极其细长，呈圆柱形或带状，直径只有几毫米，长度却可达 10–30 m 甚至更长，是已知最长的动物之一。体色多为暗褐、紫褐或红褐色，表面光滑，没有分节，身体可以大幅度伸缩和缠绕。\n\n它生活在东北大西洋的泥沙和石缝中，白天藏在洞里，夜间出来活动，取食蠕虫、甲壳动物和腐肉。纽虫最特别的结构是吻部：平时收在体内，捕食或受惊时能迅速翻出，缠绕猎物或吓退敌人。它的身体柔软但结实，断裂后可以再生。纽虫在海洋生态中是底栖捕食者之一，也是研究动物再生和身体结构演化的材料。由于身体细长、行踪隐蔽，野外观察记录并不多。纽虫的吻部表面有黏液和细刺，能牢牢缠住猎物。",
