    description: "海豆芽有两片绿色或褐绿色的壳，壳呈舌形或长椭圆形，长约 3–5 cm，壳面光滑，有细密的生长纹；壳的后端伸出一根粗壮的肉茎，用来在泥沙中挖洞和固定身体。它属于腕足动物门，外形像双壳贝类，但内部结构不同。\n\n它生活在潮间带和浅海的泥沙底，用肉茎在泥沙中挖洞穴居，靠壳内的触手冠滤食浮游生物和有机颗粒。海豆芽是著名的活化石，从 5 亿多年前的寒武纪一直延续至今，形态变化很小。它分布于中国南方、日本、东南亚和澳大利亚北部沿海，在中国潮汕等地被采食，俗称海豆芽。由于采挖和滩涂开发，部分地区的资源有所减少，采捕时需要控制强度。",
