    description: "淡水海绵的群体呈不规则的团块、树枝状或薄层状，附着在水草、石块和木桩上，表面有许多小孔，体色从灰白、黄褐到绿色都有；绿色的个体是因为体内共生了绿藻。它没有真正的组织和器官，靠领细胞鞭毛带动水流。\n\n它生活在清水湖泊、池塘和缓流溪流中，滤食细菌、藻类和有机微粒，是水体中的天然过滤器。环境恶化时，淡水海绵会形成芽球，芽球能耐受低温和干燥，等环境改善后再萌发。它分布于北半球的淡水水体，水质清洁、污染少的地方更容易见到。淡水海绵可作为水质良好的指示生物，但它也会附着在管道和养殖设施上，造成一定影响，清理时要注意保护水体生态。",
