    description: "太阳海星的腕多达 8–12 条，围绕中央盘呈放射状排列，展开时像一轮太阳，直径可达 20–30 厘米。体色多为橙红色、红色或紫红色，表面布满小棘和颗粒，腕的基部较宽，向末端逐渐变细。\n\n它分布于北太平洋的冷水海域，从日本北部、俄罗斯远东到北美西海岸，栖息于岩礁、砂泥底和潮下带，水深 0–300 米。太阳海星是肉食性动物，以海参、海鞘、海胆、贝类和小型底栖动物为食，靠管足和腕把猎物抱住送入口中。繁殖期在春季，雌雄个体释放精卵，受精卵发育为浮浪幼虫。太阳海星在冷水底栖食物网中处于较高位置，对控制海参等猎物的数量有一定作用。",
    habitat: "北太平洋冷水海域的岩礁、砂泥底和潮下带",
