    summary: "印度洋—太平洋珊瑚礁的黑色海胆，棘刺细长中空且带毒，刺伤剧痛，夜间出来啃食藻类，是礁区重要的植食者。",
    description: "刺冠海胆的壳径 5–9 厘米，棘刺细长如针，长可达 10–30 厘米，黑色并带蓝色或白色细纹，棘刺中空、易折断，内部含有毒液。壳中央有蓝灰色或白色的肛乳突，是它区别于近缘种的特征。\n\n它分布于印度洋—太平洋的热带珊瑚礁，常见于礁坪、海草床和沙泥底，水深 0–30 米，白天藏在珊瑚缝隙和岩石下，夜间成群出来啃食藻类，对控制礁区藻类过度生长有重要作用。刺冠海胆的棘刺刺入皮肤后会折断并释放毒液，引起剧痛、红肿和灼热感，严重时可能感染；被刺后应尽快取出残刺，用热水浸泡并及时就医。它在加勒比海等地曾因疾病大量死亡，导致藻类暴发，说明其对礁区生态平衡的重要性。",
