    summary: "栖居在潮间带泥沙中的大型多毛类，身体红褐、分节明显，是海钓常用的活饵，也常被用作鱼虾养殖的饵料生物。",
    description: "岩虫体长20–40厘米，宽约0.5–1厘米，身体由一百多个体节组成，每节两侧生有疣足和成束的刚毛，背面呈红褐或暗红色，腹面较浅。头部有数条触须和一对颚，颚坚硬呈黑褐色，咬合有力。\n\n它穴居在潮间带中低潮区的泥沙滩涂和河口，洞穴常呈分支状，退潮后可在滩面上看到成片的孔口。岩虫是杂食性的沉积取食者，吞食泥沙中的有机碎屑和小型生物。繁殖季节，成熟的个体变态为生殖个体，夜间群浮到水面排卵排精。由于蛋白质含量高、耐挂钩，岩虫是海钓最常用的活饵之一，被大量翻沙挖取，过度采挖会破坏滩涂结构，影响其他底栖生物。退潮后翻开的石块和贝壳下面，也常能见到它盘曲的身体。",
