    summary: "会钻入牡蛎、贻贝等贝壳内部生活的黄色海绵，靠化学溶解与机械磨蚀开出孔道，是贝类养殖业头疼的敌害生物。",
    description: "穿贝海绵的群体呈黄色、橙黄色或硫黄色，多为块状或葡萄串状，直径5–20厘米，表面有许多小孔，孔口处伸出细小的突起。它没有固定的外形，会随附着基的形状而变化，被贝壳包住时只剩下一个个黄色小点露在外面。\n\n幼体附着到贝壳或石灰岩表面后便开始钻孔：一方面分泌酸性物质溶解碳酸钙，一方面靠细胞机械磨蚀，逐渐在壳内开出直径1–3毫米的孔道。被钻穿的贝壳变脆、易碎，牡蛎和贻贝的生长与商品价值都受到影响，是贝类养殖的主要敌害之一。穿贝海绵靠滤食水中的细菌和有机颗粒为生，可进行有性繁殖，也能出芽增殖。它分布于北大西洋、地中海和北美东岸，中国沿海有近缘种类。",
