    description: "长吻沙蚕体长10–30厘米，身体细长，体节数目多，体色呈血红、粉红或肉红色，这是因为它体内含有血红蛋白。它的吻部可以像翻手套一样外翻出来，末端有四个黑色的颚钩，用于捕捉小型动物。\n\n它穴居在潮间带和浅海的泥沙底质中，退潮后的泥滩上常能看到它弯曲的洞穴和粪粒。长吻沙蚕是肉食性动物，夜间出来活动，靠外翻的吻部捕捉小蠕虫、甲壳类等。它也是日本、韩国和中国沿海常用的钓饵，被大量采挖。需要留意的是，它的颚钩能刺破皮肤并注入毒液，被咬后局部会疼痛、麻木、红肿，处理活体时应戴手套，避免直接用手抓取。它的洞穴口常堆着一圈松散的泥沙，是野外寻找它的线索。",
