    description: "笄蛭涡虫体长10–30厘米，宽仅2–3毫米，身体扁平而柔软，头部膨大成半月形或锤状，两侧各有一个黑色的眼点。体背多为黄褐色或黑褐色，常带深浅相间的纵纹，腹面颜色较浅；爬行时分泌黏液，留下一条发亮的痕迹。\n\n它生活在潮湿的花园、温室、落叶堆和石缝中，靠化学感受追踪蚯蚓和蛞蝓，捕到猎物后从口中翻出咽部将其消化。笄蛭涡虫主要靠横分裂繁殖，身体断成两段后各自再生，再生能力极强。它原产东南亚，随园艺苗木和土壤扩散到全球温暖地区的温室与庭院，成为入侵物种，对当地蚯蚓种群构成威胁。它体内含河豚毒素，用于麻痹猎物和防御天敌，虽不主动攻击人，但接触后应洗手，并防止儿童和宠物误食。",
