    taxonomy: { phylum: "线虫动物门", class: "刺嘴纲", order: "鞭虫目", family: "鞭虫科", genus: "鞭形属" },
    summary: "形似长鞭的肠道线虫，前段细长钻入肠黏膜吸血，卵随粪便排出，人因误食被粪便污染的泥土或蔬菜而感染。",
    description: "毛首鞭形线虫成虫长3–5厘米，身体前段细长如鞭梢，约占全长的五分之三，后段粗短，形似鞭柄，“鞭虫”之名由此而来。它用细长的前端钻入盲肠和结肠的黏膜内，靠吞食组织液和血液为生。\n\n虫卵随粪便排出体外，在温暖潮湿的土壤中经过约两三周发育成含幼虫的感染性卵。人通过粪口途径感染：误食被粪便污染的蔬菜、瓜果、饮用水，或接触污染土壤后不洗手就进食。虫卵在小肠孵出幼虫，幼虫钻入肠黏膜，再回到肠腔发育为成虫。轻度感染常无明显症状，重度感染可出现腹痛、腹泻、贫血，儿童还可能发生直肠脱垂。预防应改水改厕、饭前便后洗手、蔬菜洗净、粪便无害化处理，流行区可集体服用阿苯达唑或甲苯咪唑驱虫。",
    habitat: "人体盲肠与结肠黏膜，虫卵在温暖潮湿的土壤中发育",
