    description: "美洲钩虫成虫长约7–11毫米，身体呈细长的圆柱形，前端有一个发达的口囊，口囊内有两对切板，用来咬破宿主肠壁吸血。它咬附在肠黏膜上，一边吸血一边更换附着部位，伤口不断渗血。\n\n虫卵随粪便排出，在温暖潮湿、荫蔽的土壤中孵出杆状蚴，约一周后发育成丝状蚴，也就是感染期幼虫。丝状蚴可从皮肤钻入人体，赤脚下田、接触污染土壤时最容易被感染，钻入处常出现瘙痒性皮疹，俗称粪毒；幼虫随血流到肺，穿过肺泡上行至咽部，被吞咽后在小肠发育为成虫。它也可经口感染。患者常表现为贫血、乏力、面色苍黄、异食癖，儿童还会生长迟缓。预防要穿鞋下地、粪便无害化处理、饭前洗手，流行区定期驱虫。",
