      { label: "转续宿主", value: "蛙、蛇、猪等" },
      { label: "感染途径", value: "生食蛙蛇肉、饮生水、用生蛙肉敷贴伤口" },
      { label: "防护", value: "不食生蛙蛇、饮水煮沸、不用生蛙肉敷贴" },
      { label: "治疗", value: "以手术取出裂头蚴为主" }
