    summary: "形似倒置草鞋的单细胞纤毛虫，靠纤毛摆动在水中前进，以细菌和有机碎屑为食，是观察单细胞动物的经典材料。",
    description: "草履虫体长180–300微米，身体呈长椭圆形，前端钝圆，后端稍尖，形状像一只倒置的草鞋，因此得名。它全身布满纤毛，纤毛有节奏地摆动，使虫体一边旋转一边前进；体侧有一条凹入的口沟，沟底是胞口，食物由这里进入。\n\n草履虫以细菌、有机碎屑和微小的藻类为食，食物在食物泡中被消化吸收。它的细胞质里有大小两个细胞核，前后两端各有一个伸缩泡，负责排出多余的水分。草履虫通过横二分裂进行无性繁殖，也会通过接合生殖交换核物质，增加遗传多样性；环境恶化时，它能形成包囊度过不良条件。它生活在池塘、沟渠、稻田等静水水体中，富营养化的水里数量最多，是水质监测的指示生物，也是实验室常用的模式生物。",
