    description: "大变形虫的体长200–500微米，肉眼几乎看不见，在显微镜下像一个不规则的胶质团。它的身体分为外质和内质，外质透明，内质颗粒较多，细胞核、食物泡和伸缩泡都藏在内质里。运动时，细胞质向一个方向流动，伸出指状的伪足，整个身体随之向前挪动。\n\n大变形虫用伪足包围细菌、藻类和有机颗粒，把它们吞进细胞形成食物泡，再靠酶消化吸收。它生活在淡水池塘、湖泊的浅水底部，常在水草、腐叶和淤泥表面缓慢爬行。环境适宜时，它通过二分裂繁殖；干旱或低温时，则缩成球形的包囊，待条件好转再恢复活动。需要说明的是，大变形虫本身并不致病，引起阿米巴痢疾的是另一种叫溶组织内阿米巴的原虫，二者不能混为一谈。它也是研究细胞运动、吞噬和膜结构的经典实验材料。",
