    taxonomy: { phylum: "眼虫门", class: "眼虫纲", order: "眼虫目", family: "眼虫科", genus: "眼虫属" },
    summary: "有叶绿体、能进行光合作用又会游泳的单细胞生物，兼具动植物特征，是课堂里讲解“亦动亦植”的经典例子。",
    description: "眼虫体长15–100微米，身体呈梭形，前端有一根细长的鞭毛，靠鞭毛旋转在水中前进。它的前端还有一个红色的眼点，能感知光线强弱，引导虫体游向光照合适的地方。细胞内含有叶绿体，可以像植物一样进行光合作用。\n\n眼虫最特别之处在于它的营养方式：有光时进行光合作用自养，黑暗环境中则吸收水中的有机质异养，这种既能自养又能异养的方式称为混合营养。它没有细胞壁，只有一层富于弹性的表膜，因此身体可以改变形状。环境不良时，眼虫会缩成包囊。它生活在富含有机质的池塘、沟渠和稻田中，大量繁殖时会使水面泛起绿色或红色的膜，是水体富营养化的指示生物之一，也是生物学研究常用的材料。",
    habitat: "富含有机质的淡水池塘、沟渠与稻田，静水富营养水体多见",
