    taxonomy: { phylum: "眼虫门", class: "动质体纲", order: "锥虫目", family: "锥虫科", genus: "利什曼属" },
    summary: "由白蛉叮咬传播、寄生于人体巨噬细胞内的原虫，可引起长期发热、肝脾肿大、贫血和皮肤变黑，俗称黑热病。",
    description: "利什曼原虫在人体内以无鞭毛体（又称利杜体）的形式存在，虫体只有2–4微米，圆形或卵圆形，寄生在巨噬细胞内。在白蛉体内，它则变成前端有一根鞭毛的前鞭毛体，能够自由活动。\n\n当雌性白蛉叮咬患者或病犬时，吸入含无鞭毛体的巨噬细胞，虫体在白蛉胃内转变为前鞭毛体并大量繁殖；白蛉再次吸血时，前鞭毛体被注入人体，很快被巨噬细胞吞噬，却在细胞内顽强存活、繁殖，随血流散布到肝、脾、骨髓和淋巴结，引起内脏利什曼病。患者表现为长期不规则发热、肝脾肿大、贫血、白细胞减少，皮肤逐渐色素沉着，因此得名黑热病。预防以防蛉为主：使用蚊帐、纱窗和驱虫剂，管理病犬，治疗可用锑剂或两性霉素B。我国已基本消除该病，但仍需监测。",
    habitat: "人体和犬等动物的巨噬细胞内，传播阶段在白蛉消化道",
