    summary: "寄生于人体泌尿生殖道的鞭毛原虫，主要通过性接触传播，引起滴虫性阴道炎，男性感染者多无明显症状。",
    description: "阴道毛滴虫只有滋养体一个阶段，没有包囊。滋养体长10–30微米，呈梨形或椭圆形，前端有四根鞭毛，体侧有一片波浪状的波动膜，靠鞭毛和波动膜的摆动前进。它生活在人体的泌尿生殖道内，以二分裂方式繁殖。\n\n女性感染后，虫体寄居在阴道和尿道，引起滴虫性阴道炎，表现为黄绿色泡沫状白带、外阴瘙痒和尿痛；男性感染多无明显症状，或仅有尿道炎，因此容易成为传染源。传播途径以性接触为主，也可通过共用浴巾、浴盆、泳衣等间接传播，但相对少见。预防要注意安全性行为、伴侣同时治疗、不共用毛巾和浴具。阴道毛滴虫在外界环境中抵抗力较弱，离开人体后很快死亡，干燥和阳光直射都能将其杀死。治疗常用甲硝唑或替硝唑，治疗期间应避免饮酒。",
