    description: "结肠小袋纤毛虫是人体最大的寄生性原虫，滋养体长30–150微米，最大可达200微米，呈卵圆形，全身布满纤毛，前端有一个胞口，靠纤毛摆动取食淀粉颗粒和细菌。环境不利时，它分泌囊壁形成包囊，包囊直径40–60微米。\n\n包囊随粪便排出，在潮湿环境中能存活数周，污染水源和蔬菜。人误食包囊后，虫体在小肠脱囊，进入结肠定居，以肠内容物为食。猪是重要的传染源，猪的感染率往往很高，人与猪接触密切的地区发病率也较高。多数感染者没有症状，部分人出现腹痛、腹泻、黏液血便，重度感染可导致肠穿孔。预防要加强猪粪管理、保护水源、饭前便后洗手、蔬菜水果洗净；治疗可选用四环素或甲硝唑。我国病例多与接触猪有关。",
