    description: "帆水母的浮囊体扁平，呈椭圆形，长3–10厘米，颜色为鲜艳的钴蓝或蓝紫色，中央竖立着一片三角形的帆，像一艘小帆船。浮囊下方垂着短小的触手和生殖体，整体由多个特化的个体组成，并非单一只水母。\n\n有趣的是，帆水母的帆向由遗传决定：有的群体帆朝左，有的朝右，这决定了它们被风吹向哪一侧，也解释了为什么不同海域的搁浅群体常呈不同方向。帆水母生活在暖温带和亚热带的开阔海面，靠风和洋流漂移，触手捕捉浮游生物。大量聚集时，它们会成片被冲上海滩，干枯后像一层蓝白色的塑料片。它的蜇伤比僧帽水母轻得多，但皮肤敏感者仍会红肿、瘙痒；搁浅的个体也仍可能蜇人，不要赤手捡拾。",
