    description: "银币水母的浮囊体是一个扁平的圆盘，直径2–3厘米，颜色从蓝绿、黄褐到铜色不等，中央有一个口，边缘环生一圈短小的触手，看上去像一枚漂在水面的硬币，因此得名。它同样不是单一个体，而是由营养体、生殖体和触手等组成的群体。\n\n它漂浮在热带和亚热带海面的表层，靠风和洋流移动，有时成千上万只聚集成片。触手捕捉浮游生物和鱼卵，送入口中由整个群体分享。银币水母的蜇伤比较轻微，多数人只会感到刺痛或出现红斑，但敏感体质者可能红肿、瘙痒，过敏反应明显时应及时就医。它常与帆水母一起被冲上海滩，搁浅后仍可能蜇人。观察时不要赤手抓取，也不要让碎屑揉进眼睛。它广泛分布于全球温暖海域，中国南海和东南沿海可见。",
