    description: "瓜水母的身体呈瓜形或袋状，长约10–15厘米，通体透明，常带淡淡的粉红或乳白色，表面有八列纵行的栉板。栉板由一排排纤毛黏合而成，像梳子一样，划动时折射出彩虹般的光泽。它没有触手，前端是一个能张大的口。\n\n瓜水母属于栉水母动物门，和真正的钵水母、水螅水母不是一类，它没有刺细胞，不会蜇人。它是凶猛的捕食者，专吃其他栉水母，比如球栉水母和海醋栗，靠大嘴整个吞下猎物，再用体内的酶消化。瓜水母靠栉板划水缓慢游动，受到刺激时会发出蓝绿色的生物光。它分布在北大西洋、北太平洋和北冰洋边缘的温带、寒带海域，中国北方沿海偶见。近年栉水母在部分海域大量繁殖，捕食鱼卵和幼鱼，对渔业资源造成影响，因此受到生态学家的关注。",
