    description: "薮枝螅的群体高2–5厘米，呈白色或淡褐色，分枝细长，像一棵小树或一丛羽毛。每个分枝顶端有一个钟形的水螅体，口周围环生触手，用来捕捉浮游生物；群体基部附着在海藻、岩石或船底上。\n\n它的生活史有明显的世代交替：水螅体通过出芽产生生殖体，释放出直径只有1–3毫米的水母体；水母体在海中浮游，进行有性繁殖，受精卵发育成浮浪幼虫，附着后长成新的水螅群体。薮枝螅常附生在海带等大型海藻的叶片上，也是码头、船底和养殖网箱上的污损生物。它的刺细胞虽然微小，却能引起接触性皮炎，潜水员、渔民和游泳者接触后皮肤会出现红肿、瘙痒和灼痛，因此被称为海荨麻疹。接触后应用海水冲洗，避免抓挠，症状明显时及时就医。",
