    description: "多孔蔷薇珊瑚的群体由许多直立或斜伸的指状分枝组成，分枝圆柱形，末端钝圆，高度可达二十厘米。它的骨骼表面密布细小的孔洞，每个孔里居住着一只水螅体，孔口周围有细密的刺状突起，多孔之名由此而来。活体表面覆盖一薄层共肉，颜色多为淡褐、黄褐、淡紫或蓝紫，分枝顶端常呈淡色或荧光色。\n\n它分布于印度洋至西太平洋的热带珊瑚礁海区，包括中国南海、日本南部、菲律宾、印度尼西亚和大堡礁，栖息在潮间带下区至水深二十米的礁坪、礁坡和潟湖，喜欢光照充足、水流中等的位置。它体内共生虫黄藻，靠光合作用获得主要能量，同时捕食浮游动物。它是雌雄同体或雌雄异体的造礁珊瑚，繁殖期在春夏，幼虫浮游后附着变态，生长速度在石珊瑚中较快。它对海水升温非常敏感，热浪来临时容易大面积白化死亡，目前尚无专门的保护级别，但珊瑚礁整体受气候变化和海水污染威胁。",
