    description: "花刺参的体长可达三十至四十厘米，体呈长圆筒形，背面隆起，腹面平坦。它的背面散布着大小不等的疣足和肉刺，沿着背中线有两列较大的疣足，腹面则密布管足，用来爬行和附着。体色变化较大，有黄褐、灰绿、墨绿等底色，上面缀有深浅相间的斑块和网纹，花刺参之名由此而来。体壁厚实，富含胶原。\n\n它分布于印度洋至西太平洋的热带海区，包括中国南海、菲律宾、印度尼西亚和澳大利亚北部，栖息在潮间带下区至水深三十米的珊瑚礁沙底、礁坪和潟湖，白天多藏在礁石下或沙中，夜间出来活动，用触手状的口部舔食沙泥中的有机碎屑、藻类和微生物。它是雌雄异体，繁殖期在春夏，幼虫浮游后附着变态。它是南海重要的食用海参，肉质厚实，干制后是名贵海味，长期过度捕捞使野生资源明显下降，目前尚无国际公约级别的保护，中国已在部分海区实施禁捕和增殖放流。",
