    category: "other-invertebrates",
    aliases: ["蓝氏贾第虫", "梨形虫"],
    taxonomy: { phylum: "双滴虫门", class: "鞭毛虫纲", order: "双滴虫目", family: "贾第虫科", genus: "贾第虫属" },
    summary: "寄生于小肠的鞭毛虫，包囊随粪便排出并污染水源，经口感染引起腹泻，是常见的水源性肠道寄生虫。",
    description: "贾第虫的生活史分为滋养体和包囊两个阶段。滋养体呈梨形，长约十至二十微米，两侧对称，有八根鞭毛和两个细胞核，腹面有一个吸盘状的结构，用来吸附在小肠黏膜上。包囊呈椭圆形，直径约十微米，囊壁厚实，能在外界存活数周至数月，对氯消毒有较强的耐受性。\n\n它呈世界性分布，在中国的感染率在部分地区仍然较高，宿主包括人、犬、猫、牛和野生动物。感染途径是粪口传播：包囊随粪便排出，污染饮水、食物、蔬菜或手，被人吞食后在小肠脱囊成为滋养体，吸附在肠壁上繁殖，引起贾第虫病，表现为腹泻、腹痛、腹胀、恶心和吸收不良，病程可长达数周。饮用未煮沸的溪水、井水或在卫生条件差的地区进食生冷食物是主要风险，水厂常规氯消毒不能可靠杀灭包囊。防护的关键是饮用煮沸的水或经正规过滤的水，饭前便后洗手，蔬果洗净，野外徒步时不直接饮用溪水。",
    habitat: "人或动物的小肠上段，包囊随粪便排入水体与土壤",
    distribution: "世界性分布，中国部分地区感染率仍较高",
