    summary: "寄生于肠道上皮的球虫类原虫，卵囊极耐氯并能抗多数消毒剂，经污染饮水与动物粪便感染，引起水样腹泻。",
    description: "隐孢子虫是一种细胞内寄生的原虫，生活史包括卵囊、子孢子、滋养体和裂殖体等阶段。感染性卵囊呈球形，直径约四至六微米，囊壁厚实，内含四个裸露的子孢子。卵囊对外界环境抵抗力极强，能在潮湿环境中存活数月，对常规浓度的氯、臭氧以外的多数消毒剂都不敏感。\n\n它呈世界性分布，宿主包括人、牛、羊、犬、猫和多种野生动物。感染途径主要是粪口传播：卵囊随粪便排出，污染饮水、牛奶、蔬果或手，被吞食后在肠道上皮细胞内寄生繁殖，破坏肠绒毛，引起隐孢子虫病，表现为大量水样腹泻、腹痛、恶心和脱水，免疫功能低下者病情可迁延甚至危及生命。奶牛场、托幼机构和游泳池是常见的暴发场所。防护的关键是把水煮沸至少一分钟，使用能截留卵囊的微孔滤膜，接触动物后彻底洗手，不喝生牛奶，免疫功能低下者尤其要避免接触腹泻的幼畜。目前尚无特效药物，治疗以补液为主。",
