    description: "菊花海鞘是群体生活的尾索动物，每个个体称为个虫，长约二至三毫米，呈长椭圆形，外包一层透明的胶质被囊。数个至十余个个虫围绕一个共同的出水孔排列，形成一朵星形或菊花形的小群，小群再彼此相连，铺成一片。群体颜色变化极多，有橙黄、紫红、墨绿、淡蓝和白色，常在同一块石头上出现几种颜色。\n\n它分布于北大西洋、地中海和北太平洋的温带海岸，在中国北方沿海有记录，栖息在潮间带至水深数米的岩石、海藻、贝壳、船底和码头桩柱上。每个个虫各有一个入水孔，靠鳃裂上的纤毛滤食浮游藻类和有机颗粒，废水从共同的出水孔排出。它雌雄同体，既能通过出芽进行无性繁殖，也能进行有性生殖，幼虫浮游数小时后附着变态。它是全球性的污损生物，会附着在船底、养殖网笼和水下设施上，与贝类争夺空间和饵料，目前尚无保护级别。",
