    summary: "群体呈紫色分枝状、表面布满大孔的海绵，没有组织和器官，靠鞭毛细胞抽水滤食，栖息于潮下带硬质海底。",
    description: "紫海绵的群体呈直立的树枝状或管状，高可达二十厘米，分枝圆柱形，末端钝圆或略扁，基部附着在礁石上。它的体色紫褐至深紫，表面密布大小不等的入水孔，中央有较大的出水孔，管壁薄而有弹性，压下去能回弹，像一块多孔的橡胶。它的骨骼由细小的硅质骨针和海绵丝构成，支撑着柔软的躯体。\n\n它分布于北大西洋和北太平洋的温带与寒带海域，栖息在潮下带至水深一百米以上的岩礁、砾石和贝壳底，喜欢水流较强、悬浮物丰富的位置。海绵没有真正的组织和器官，靠体内的领鞭毛细胞制造水流，把水中的细菌、浮游藻类和有机颗粒滤下来，一只个体的滤水量每天可达自身体积的许多倍。它雌雄同体，可进行有性生殖，也能通过断枝进行无性繁殖。它常与海葵、苔虫和蛇尾共栖，体内还能住进小虾和鱼。它尚无保护级别，底拖网和海水污染会破坏其栖息地。",
