    description: "绿水螅的体长约一至两厘米，身体呈细长的圆筒形，一端是基盘，能分泌黏液附着在水草和石块上，另一端是口盘，口的周围环生五至七条细长的触手。它的身体呈透明的绿色，这种绿来自体内共生的单细胞绿藻，绿藻通过光合作用为水螅提供部分养分，水螅则为绿藻提供庇护和代谢废物。\n\n它分布于世界各地的淡水池塘、湖泊、沟渠和缓流溪中，在中国南北方的清水水体中都可见到，喜欢水质清洁、光照充足、水草丰茂的环境。它用触手上的刺细胞麻痹水蚤、剑水蚤和幼虫等小型甲壳类，再用触手送入口中。它没有性别分工的群体，平时靠基部的出芽生殖产生新个体，环境不利时进行有性生殖并形成休眠胚。它的再生能力极强，被切成数段后每段都能长成完整个体。它尚无保护级别，是淡水生态和再生研究中的经典实验动物，水体污染会使其数量减少。",
