    description: "威廉环毛蚓的体长十五至二十厘米，体呈圆柱形，由一百多个体节组成，体色灰褐至红褐，背部颜色较深，腹部较浅。它的环带位于第十四至十六节，呈肿胀的环状，颜色较浅，性成熟时格外明显。除第一节和最后几节外，每个体节上都环生一圈细小的刚毛，刚毛是它钻土时的支点，环毛蚓之名由此而来。\n\n它分布于中国华北、华东和华中的农田、菜园、果园和庭院土壤中，喜欢湿润、富含有机质的壤土，穴居深度可达数十厘米，白天在洞中活动，夜间爬到地表取食腐叶和有机碎屑，把泥土吞入消化道，吸收其中的有机质后排出团粒状的蚓粪，能显著改善土壤的通气性和肥力。它雌雄同体，异体交配，卵产于卵茧中。雨前气压降低、土壤缺氧时，它会爬出地面，因此常被误认为下雨招来了蚯蚓。它尚无保护级别，是重要的土壤动物，也被用作钓饵和中药材，过量捕捉和农药使用会影响其种群。",
