    taxonomy: { phylum: "有孔虫门", class: "轮虫纲", order: "轮虫目", family: "轮虫科", genus: "氨盘虫属" },
    summary: "壳径不足一毫米、带多个小室的钙质壳单细胞生物，栖息于潮间带泥沙中，是判断水质与古环境的指示生物。",
    description: "有孔虫是一类单细胞的原生生物，氨盘虫的壳径通常只有零点五毫米左右，壳由碳酸钙构成，呈螺旋状卷曲，分为若干个逐渐增大的小室，小室之间有隔板，壳面密布细小的孔，伪足从孔中伸出，有孔虫之名由此而来。壳质半透明，呈灰白至淡黄，在显微镜下像一枚精致的微型螺壳。\n\n它分布于世界各地的潮间带、河口和浅海泥沙底，在中国沿海的滩涂和养殖池塘中很常见，营底栖生活，靠伪足在泥沙颗粒之间移动，捕食细菌、藻类和有机碎屑。它耐受低氧和有机污染的能力较强，在污染严重的沉积物中往往成为优势种，因此被广泛用作水质和生态健康监测的指示生物；它的壳还能保存在沉积物中，为古气候和海平面变化研究提供材料。它通过分裂进行无性生殖，也可进行有性生殖。它尚无保护级别，是微体古生物学和生态学研究的重要对象。",
    habitat: "潮间带、河口与浅海的泥沙底，营底栖生活",
