      { label: "免疫逃避", value: "不断更换体表糖蛋白包被" },
      { label: "感染途径", value: "舌蝇叮咬，随蝇唾液注入人体" },
      { label: "症状", value: "发热、淋巴结肿大，后期睡眠紊乱与昏迷" },
      { label: "防护", value: "穿长袖、用驱虫剂、避开河岸灌丛" }
