    description: "心形海胆的壳长约五至八厘米，壳形不规则，前端略尖，后端钝圆，从背面看呈心形，壳面覆有短而密的黄褐色棘刺，棘刺向后倾斜，便于在沙中挖掘。它的口位于壳的前端腹面，肛门在后端，步带区呈花瓣状，管足特化为呼吸和取食的构造，整体外形与常见的球形海胆差别很大。\n\n它分布于欧洲大西洋沿岸、地中海至东亚的沙质海底，栖息在潮下带至数十米深的细沙中，垂直埋栖，深度可达二十厘米，靠管足在沙内收集有机碎屑。它挖掘时会把沙粒通过棘刺和管足搬运，在沙面形成隆起的痕迹，退潮后的沙滩上常能看到。它以沉积物中的有机颗粒为食，是沙质海底重要的沉积食性动物，拖网和挖沙会破坏其栖息环境。",
