    description: "玉足海参的体长约二十至三十厘米，体呈圆筒形，体壁厚实，背面黑褐至灰黑色，腹面颜色较浅，管足密集，末端常带白色，玉足之名由此而来。体表散布疣足和细小突起，口周围有二十枚枝状触手，用于抓取沙粒送入口中。它行动缓慢，靠管足在沙底爬行。\n\n它分布于印度洋至西太平洋的热带珊瑚礁，从东非、东南亚到中国南海和澳大利亚北部，栖息在礁坪、潟湖的沙底和珊瑚碎石区。它以触手抓取含有机质的沙粒，是海底的清道夫。受惊时它会从肛门喷出白色的居维氏管，黏住天敌后自行断落，随后再生。它是食用海参的一种，在东南亚和中国南方被大量采捕，野生资源下降明显，现已开展人工增养殖。",
