    summary: "寄生于鼠类肺动脉的线虫，幼虫经螺类中间宿主传播，人误食生螺或污染蔬菜可致嗜酸性脑膜炎。",
    description: "广州管圆线虫的成虫体细长，雌虫长约二十至三十毫米，雄虫略短，寄生于鼠类的肺动脉内。雌虫产卵后，卵在肺毛细血管中孵化，幼虫穿过肺泡进入气管，被咽下后随粪便排出。幼虫在外界需进入螺类或蛞蝓体内才能继续发育，在螺体内经两次蜕皮成为感染性幼虫。\n\n它的终宿主是鼠类，中间宿主包括福寿螺、褐云玛瑙螺等陆生螺类和蛞蝓。人因生食或半生食螺肉、蛞蝓，或食用被其黏液污染的蔬菜而感染。幼虫进入人体后多移行至脑部，引起嗜酸性脑膜炎。该病在中国南方、东南亚和太平洋岛屿有分布，与生食螺类的习惯密切相关。防护措施包括彻底煮熟螺肉、生熟分开、清洗蔬菜，出现头痛发热应及时就医并告知饮食史。",
