    description: "布氏姜片吸虫的成虫体长二十至七十五毫米，体宽八至二十毫米，是寄生于人体最大的吸虫之一。虫体扁平肥厚，形如一片姜，前端略尖，后端钝圆，口吸盘小，腹吸盘较大，位于体前部。虫体寄生于人和猪的小肠上段，靠吸盘附着肠壁，取食肠内容物和血液，虫体本身呈肉红色。\n\n它的虫卵随粪便排出，在水中孵出毛蚴，钻入扁卷螺等中间宿主发育成尾蚴，尾蚴逸出后在水生植物表面结囊成囊蚴。人生食菱角、荸荠、茭白、水芹等附着囊蚴的水生植物即感染，猪是重要的保虫宿主。感染轻者无症状，重者腹痛、腹泻、浮肿。该病主要分布于中国南方及东南亚，防护在于不生食水生植物、不喝生水，并对猪进行驱虫管理。",
