    description: "巴贝虫是一种寄生于红细胞内的原虫，虫体微小，呈环形或梨形，长约二至三微米。它由硬蜱传播，在蜱体内完成部分发育，随蜱的唾液进入人体后侵入红细胞，在细胞内分裂繁殖，使红细胞破裂。它的形态与疟原虫相似，但不会在红细胞内产生色素，这是镜下鉴别的重要区别。\n\n它的自然宿主是啮齿类，尤其是白足鼠，经肩突硬蜱叮咬传播，人因被感染的蜱叮咬而患病。潜伏期一至四周，症状包括高热、寒战、乏力、溶血性贫血和脾肿大，免疫力低下者可能重症。该病主要分布于美国东北部和中西部，欧洲和亚洲也有近缘种。防护措施包括在林区穿长袖衣裤、使用驱蜱剂、离开后检查身体并及时清除附着的蜱。",
    habitat: "红细胞内（虫体）；林区草丛与硬蜱体内（传播环节）",
