    description: "福氏耐格里阿米巴是一种自由生活的阿米巴，有三种形态：滋养体、鞭毛体和包囊。滋养体长约十至二十五微米，靠伪足运动，在温暖水中活跃；环境不利时形成鞭毛体或包囊。它并不寄生于人体，而是自由生活在淡水、土壤和温泉中，以细菌为食，是水体微生物群落的一员。\n\n人在温暖的淡水湖泊、池塘、温泉或未充分消毒的泳池中游泳时，含阿米巴的水被搅入鼻腔，滋养体沿嗅神经进入脑部，引起原发性阿米巴脑膜脑炎。潜伏期短，病程凶险，出现头痛、发热、呕吐、颈项强直甚至昏迷，病死率极高。该病全球散发，热带和亚热带多见。防护措施包括避免在温暖淡水中跳水、潜水，游泳时使用鼻夹，不饮用未经处理的温水。",
