    summary: "群体呈紫色胶质片状、个体排成枝状的海鞘，附着于船底与养殖设施，原产西北太平洋，已成多地入侵种。",
    description: "紫拟菊海鞘是群体海鞘，群体呈薄片状或块状，厚约数毫米，表面光滑呈胶质，颜色从紫红、橙黄到淡褐不等。群体中的个体呈细长管状，排列成弯曲的分枝或链状，各自有入水管和出水管，共同埋在一个胶质基座里，一个个小孔在表面排成花纹。\n\n它原产西北太平洋，包括中国、日本和韩国沿海，随船底污损传播到北美东西海岸、欧洲和澳大利亚，成为常见的入侵污损生物。它以滤食浮游生物为生，繁殖力强，能通过群体断裂和幼虫两种方式扩散，在码头、浮筏和养殖网箱上迅速覆盖基质。它会与牡蛎、贻贝争夺附着空间，增加船体阻力，管理以定期清理和防污处理为主。",
