    description: "膜孔苔虫是群体苔藓虫，群体呈薄薄的白色网状片，由许多长方形小室排列成单层，边缘有细小的刺。群体附着在海藻叶片表面，大小可达数厘米，远看像一层白霜或细密的蕾丝，贴在海带和糖藻的叶面上，用手一摸有砂纸般的颗粒感。\n\n它原产北太平洋，包括日本和北美西海岸，二十世纪随海藻和船体传播到北大西洋，如今在北美东岸和欧洲沿海大量繁殖。它以触手冠滤食浮游生物，繁殖快，能在海藻叶片上迅速覆盖大片面积，遮挡光照、增加阻力，导致海带折断，对海带林造成影响。它是典型的海藻污损生物，扩散与海藻养殖和航运密切相关，管理需监测海藻调运和船体附着。",
